package com.yeyamo_mobile.api.moderation_trust_service.domain;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.*;
class ModerationDomainTests{@Test void enforcesTheModerationWorkflow(){var r=ModerationReport.create(TargetType.POST,"post-1","author-1","reporter-1",ReportReason.SPAM,"spam");assertEquals(ReportStatus.OPEN,r.getStatus());assertThrows(IllegalStateException.class,()->r.decide(ReportStatus.APPROVED,"mod","done"));r.startReview("mod");r.decide(ReportStatus.APPROVED,"mod","confirmed");assertEquals(ReportStatus.APPROVED,r.getStatus());assertNotNull(r.getDecidedAt());assertThrows(IllegalStateException.class,()->r.startReview("mod"));}
 @Test void trustScoreAlwaysStaysBetweenZeroAndOneHundred(){TrustScore s=TrustScore.initial("user");for(int i=0;i<20;i++)s.approvedAgainst();assertEquals(0,s.getScore());for(int i=0;i<200;i++)s.validReporter();assertEquals(100,s.getScore());}}
